-- Additive media association, never removes the original announcement or its view history.
CREATE TABLE IF NOT EXISTS publication_media(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,announcement_id BIGINT NOT NULL UNIQUE REFERENCES announcements(id) DEFERRABLE INITIALLY IMMEDIATE,author_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,storage_name TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,size BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'published',day_key TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS publication_media_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,media_id BIGINT NOT NULL REFERENCES publication_media(id) DEFERRABLE INITIALLY IMMEDIATE,storage_name TEXT NOT NULL,mime TEXT NOT NULL,size BIGINT NOT NULL,replaced_at TEXT NOT NULL,actor_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE);
